<script setup>
import {inject as injectAdminConfirmation} from 'vue'
const {confirmAction}=injectAdminConfirmation('admin')
import AdminActionMenu from '../../components/admin/AdminActionMenu.vue'
import AdminPageHeader from '../../components/admin/AdminPageHeader.vue'
import {useModalDraft} from '../../composables/useModalDraft'
import DomainFilters from '../../components/admin/DomainFilters.vue'
import {inventoryFilters,paginationFields} from '../../constants/domainFilters'
import {ref,reactive,computed,watch,inject} from 'vue'
import {inventoryApi} from '../../api/inventory.api'
import {categoriesApi} from '../../api/categories.api'
import {branchesApi} from '../../api/branches.api'
import {productsApi} from '../../api/products.api'
import {useAuthStore} from '../../stores/auth'
import {useServerList} from '../../composables/useServerList'
import {useApiState,useApiMutation} from '../../composables/useApiState'
import {formatDateTime} from '../../utils/formatters'
import RemotePicker from '../../components/admin/catalog/RemotePicker.vue'
import AdminModal from '../../components/admin/AdminModal.vue'
import DomainFields from '../../components/admin/DomainFields.vue'
import ApiFeedback from '../../components/admin/catalog/ApiFeedback.vue'
import ApiPagination from '../../components/admin/catalog/ApiPagination.vue'
const auth=useAuthStore(),{notify}=inject('admin'),tab=ref(auth.can('inventory.view')?'stock':'movements'),list=useServerList(inventoryApi,{low_stock:'',out_of_stock:'',is_tracking:'',sort:'product_name',direction:'asc'}),history=ref(null),movements=useServerList({list:(params,signal)=>inventoryApi.movements(params,signal,history.value?.id)},{type:'',date_from:'',date_to:''}),report=useApiState(),detail=useApiState(),mutation=useApiMutation(),open=ref(false),operation=ref(''),selected=ref(null),form=reactive({}),uncertain=ref(false)
const fields=computed(()=>operation.value==='create'?[{key:'opening_balance',label:'الرصيد الافتتاحي',type:'number',min:0,max:999999999.999,step:'.001'},{key:'low_stock_threshold',label:'حد تنبيه المخزون (اختياري)',type:'number',min:0,max:999999999.999,step:'.001'}]:operation.value==='configure'?[{key:'low_stock_threshold',label:'حد تنبيه المخزون (اختياري)',type:'number',min:0,max:999999999.999,step:'.001'},{key:'is_tracking',label:'تتبع المخزون',type:'checkbox'}]:[{key:'quantity',label:operation.value==='adjust'?'فرق الكمية (+ زيادة / − نقصان)':'الكمية',required:true,type:'number',min:operation.value==='adjust'?-999999999.999:.001,max:999999999.999,step:'.001'},{key:'reason',label:'السبب',type:'textarea',required:operation.value!=='receive',minlength:3,max:1000}])
const labels={create:'تهيئة المخزون',configure:'إعدادات المخزون',receive:'استلام مخزون',adjust:'تسوية المخزون',waste:'تسجيل هدر'}
const filterPickers=computed(()=>[['branch_uuid','الفرع',branchesApi,'branches.view'],['product_uuid','المنتج',productsApi,'products.view'],['category_uuid','القسم',categoriesApi,'categories.view']].filter(r=>auth.can(r[3])).map(([key,label,api])=>({key,label,api})))
function showHistory(row){history.value=row;tab.value='movements';movements.search()}
function load(){if(tab.value==='stock')return list.load();if(tab.value==='movements')return movements.load();return report.run(signal=>inventoryApi.report(list.filters,signal))}
async function edit(op,row=null){operation.value=op;selected.value=row;mutation.error.value=null;let current=row;if(row)current=await detail.run(()=>inventoryApi.show(row.id));if(row&&!current)return;Object.assign(form,{branch_uuid:'',product_uuid:'',opening_balance:'0',low_stock_threshold:current?.low_stock_threshold??'',is_tracking:current?.tracking??true,quantity:'',reason:''});open.value=true}
async function save(){if(uncertain.value)return;if(!(await confirmAction('تأكيد '+labels[operation.value]+' على الخادم؟')))return;let payload;if(operation.value==='create')payload={branch_uuid:form.branch_uuid,product_uuid:form.product_uuid,opening_balance:form.opening_balance,low_stock_threshold:form.low_stock_threshold===''?null:form.low_stock_threshold};else if(operation.value==='configure')payload={is_tracking:form.is_tracking,low_stock_threshold:form.low_stock_threshold===''?null:form.low_stock_threshold};else payload={quantity:form.quantity,reason:form.reason||null};const result=await mutation.run(()=>operation.value==='create'?inventoryApi.create(payload):operation.value==='configure'?inventoryApi.update(selected.value.id,payload):inventoryApi.action(selected.value.id,operation.value,payload));if(result.ok){open.value=false;notify('تم تسجيل تحديث المخزون.');load()}else if(!mutation.error.value?.status||mutation.error.value.status>=500){uncertain.value=true;open.value=false}}
async function reconcile(){const value=await movements.load();if(value){tab.value='movements';uncertain.value=false;mutation.error.value=null}}
watch(tab,load);load()
const beforeClose=useModalDraft(open,form,mutation.busy)
</script>
<template><main id="main"><AdminPageHeader class="page-heading"><div><span class="eyebrow">إدارة شيشلي</span><h1>المخزون</h1><p class="muted">الكميات والحجز والحركات من الخادم</p></div><button v-if="auth.can('inventory.create')" class="button" :disabled="uncertain||mutation.busy.value||detail.loading.value" @click="edit('create')">تهيئة مخزون</button></AdminPageHeader><nav class="module-tabs"><button v-if="auth.can('inventory.view')" :aria-pressed="tab==='stock'" @click="tab='stock'">الكميات</button><button v-if="auth.can('inventory.movements.view')" :aria-pressed="tab==='movements'" @click="history=null;tab='movements';movements.search()">الحركات</button><button v-if="auth.can('inventory.view')" :aria-pressed="tab==='report'" @click="tab='report'">تقرير المخزون</button></nav><p v-if="uncertain" role="alert">لم تتأكد نتيجة العملية. راجع الحركات قبل اتخاذ قرار بإعادة الإرسال. <span v-if="!auth.can('inventory.movements.view')">اطلب من موظف مخوّل مراجعة السجل قبل محاولة العملية مجددًا.</span> <button class="row-button" v-if="auth.can('inventory.movements.view')" :disabled="movements.state.loading.value" @click="reconcile">تحميل سجل الحركات</button></p><ApiFeedback variant="inline" :loading="detail.loading.value" :error="detail.error.value" @retry="detail.error.value=null"/><section v-if="tab==='stock'" class="panel"><form class="toolbar" @submit.prevent="list.search"><input v-model="list.filters.search" aria-label="بحث المخزون" maxlength="180" placeholder="بحث المنتج"><select v-model="list.filters.low_stock" aria-label="المخزون المنخفض"><option value="">كل الكميات</option><option value="1">مخزون منخفض</option></select><select v-model="list.filters.out_of_stock" aria-label="النفاد"><option value="">كل المنتجات</option><option value="1">نافد</option></select><button class="button" :disabled="list.state.loading.value">بحث</button><DomainFilters @clear="list.search()" :form="list.filters" :fields="inventoryFilters" :pickers="filterPickers" :busy="list.state.loading.value"/></form><ApiFeedback :loading="list.state.loading.value" :error="list.state.error.value" @retry="list.load"/><div v-if="list.state.data.value" class="table-wrap"><table v-admin-table><thead><tr><th>المنتج / الفرع</th><th>الموجود</th><th>المحجوز</th><th>المتاح</th><th>الحالة</th><th>الإجراءات</th></tr></thead><tbody><tr v-for="row in list.state.data.value.data" :key="row.id"><td><div class="admin-cell-value">{{ row.product.name }}<br><small>{{ row.branch.name }}</small></div></td><td><div class="admin-cell-value">{{ row.stock.on_hand }}</div></td><td><div class="admin-cell-value">{{ row.stock.reserved }}</div></td><td><div class="admin-cell-value">{{ row.stock.available }}</div></td><td><div class="admin-cell-value">{{ row.tracking?'تتبع مفعّل':'تتبع متوقف' }}<span v-if="row.is_out_of_stock" class="badge off">نافد</span><span v-else-if="row.is_low_stock" class="badge">منخفض</span></div></td><td><div class="admin-cell-value"><div class="admin-row-actions"><button v-if="auth.can('inventory.movements.view')" class="row-button" @click="showHistory(row)">سجل الحركات</button><AdminActionMenu v-if="['inventory.adjust','inventory.receive','inventory.waste'].some(permission=>auth.can(permission))"><template v-for="[op,permission] in [['configure','inventory.adjust'],['receive','inventory.receive'],['adjust','inventory.adjust'],['waste','inventory.waste']]" :key="op"><button v-if="auth.can(permission)" class="row-button" :class="{danger:op==='waste'}" :disabled="mutation.busy.value||uncertain||detail.loading.value" @click="edit(op,row)">{{ labels[op] }}</button></template></AdminActionMenu></div></div></td></tr></tbody></table><p v-if="!list.state.data.value.data.length" class="empty">لا توجد سجلات مخزون مطابقة.</p></div><ApiPagination :meta="list.state.data.value?.meta" :links="list.state.data.value?.links" :busy="list.state.loading.value" @page="list.changePage"/></section><section v-else-if="tab==='movements'" class="panel"><h2 v-if="history">حركات {{ history.product.name }} · {{ history.branch.name }}</h2><form class="toolbar" @submit.prevent="movements.search"><select v-model="movements.filters.type" aria-label="نوع الحركة"><option value="">كل الحركات</option><option v-for="value in ['opening_balance','stock_in','adjustment_in','adjustment_out','reservation','reservation_release','sale','return','waste']" :key="value" :value="value">{{ value }}</option></select><label class="field">من<input v-model="movements.filters.date_from" type="date"></label><label class="field">إلى<input v-model="movements.filters.date_to" type="date"></label><button class="button" :disabled="movements.state.loading.value">بحث</button><DomainFilters @clear="movements.search()" :form="movements.filters" :fields="paginationFields" :pickers="history?[]:filterPickers.filter(p=>p.key!=='category_uuid')" :busy="movements.state.loading.value"/></form><ApiFeedback :loading="movements.state.loading.value" :error="movements.state.error.value" @retry="movements.load"/><div v-if="movements.state.data.value" class="table-wrap"><table v-admin-table><thead><tr><th>الوقت</th><th>الحركة</th><th>الكمية</th><th>قبل / بعد</th><th>السبب</th></tr></thead><tbody><tr v-for="row in movements.state.data.value.data" :key="row.uuid"><td><div class="admin-cell-value">{{ formatDateTime(row.created_at) }}</div></td><td><div class="admin-cell-value">{{ row.type }}</div></td><td><div class="admin-cell-value">{{ row.quantity }}</div></td><td><div class="admin-cell-value">{{ row.on_hand_before }} ← {{ row.on_hand_after }}</div></td><td><div class="admin-cell-value">{{ row.reason||'—' }}</div></td></tr></tbody></table><p v-if="!movements.state.data.value.data.length" class="empty">لا توجد حركات مطابقة.</p></div><ApiPagination :meta="movements.state.data.value?.meta" :links="movements.state.data.value?.links" :busy="movements.state.loading.value" @page="movements.changePage"/></section><section v-else class="panel"><form @submit.prevent="load"><DomainFilters @clear="list.search()" :form="list.filters" :fields="inventoryFilters.filter(f=>! ['sort','direction','per_page'].includes(f.key))" :pickers="filterPickers" :busy="report.loading.value"/><button class="button" :disabled="report.loading.value">تحديث التقرير</button></form><ApiFeedback variant="stats" :loading="report.loading.value" :error="report.error.value" @retry="load"/><dl v-if="report.data.value" class="order-facts"><template v-for="[key,label] in [['tracked_products_count','المنتجات المتتبعة'],['tracked_inventories_count','سجلات المخزون'],['out_of_stock_count','النافد'],['low_stock_count','المنخفض']]" :key="key"><dt>{{ label }}</dt><dd>{{ report.data.value[key] }}</dd></template></dl></section><ApiFeedback v-if="!open" :error="mutation.error.value" @retry="mutation.error.value=null"/><AdminModal :before-close="beforeClose" v-model:open="open" :title="labels[operation]" :busy="mutation.busy.value" @submit="save"><template v-if="operation==='create'&&open"><RemotePicker v-if="auth.can('branches.view')" v-model="form.branch_uuid" :api="branchesApi" label="الفرع" :disabled="mutation.busy.value"/><RemotePicker v-if="auth.can('products.view')" v-model="form.product_uuid" :api="productsApi" label="المنتج المتتبع للمخزون" :disabled="mutation.busy.value"/><p class="form-note">التهيئة متاحة فقط لمنتج مفعّل عليه تتبع المخزون؛ الخادم يتحقق من ذلك.</p></template><DomainFields :fields="fields" :form="form" :errors="mutation.error.value?.errors" :disabled="mutation.busy.value"/><ApiFeedback :error="mutation.error.value" @retry="mutation.error.value=null"/><button class="button" :disabled="mutation.busy.value||uncertain">تأكيد العملية</button></AdminModal></main></template>
